INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7362822, 1153844, 65858, '<td valign="top">Wickedly funny and well done!</td>', 'Wickedly funny and well done!', '2015-06-15 01:07:25.000000', NULL, 1),
(7362829, 1152481, 65858, '<td valign="top">Funny joke. :) The trees and plants look a bit weird, though -- maybe oversharp? And I''ve never seen a sign look like that, feels a bit odd. So 5 from me.</td>', 'Funny joke. :) The trees and plants look a bit weird, though -- maybe oversharp? And I''ve never seen a sign look like that, feels a bit odd. So 5 from me.', '2015-06-15 01:10:23.000000', NULL, 1),
(7362832, 1152314, 65858, '<td valign="top">Ha ha, subliminal voting message? It worked, 6 from me. =) I like the intrigue.</td>', 'Ha ha, subliminal voting message? It worked, 6 from me. =) I like the intrigue.', '2015-06-15 01:11:25.000000', NULL, 1),
(7362838, 1153371, 65858, '<td valign="top">Lovely scenery! The colors are a bit psychedelic, but I don''t mind it. 7!</td>', 'Lovely scenery! The colors are a bit psychedelic, but I don''t mind it. 7!', '2015-06-15 01:13:24.000000', NULL, 1),
(7362842, 1153407, 65858, '<td valign="top">Aww, lovely photo! Feels like a lot of space between the kids and the sign, but that''s only a nit. 7</td>', 'Aww, lovely photo! Feels like a lot of space between the kids and the sign, but that''s only a nit. 7', '2015-06-15 01:14:17.000000', NULL, 1),
(7362843, 1153555, 138630, '<td valign="top">Great sign, nice composition, love the starburst on the street light.</td>', 'Great sign, nice composition, love the starburst on the street light.', '2015-06-15 01:14:27.000000', NULL, 1),
(7362844, 1153780, 65858, '<td valign="top">I like the grunge, nice textures.</td>', 'I like the grunge, nice textures.', '2015-06-15 01:14:55.000000', NULL, 1),
(7362847, 1153938, 93283, '<td valign="top">Bonus points for a Vanilla Ice reference...</td>', 'Bonus points for a Vanilla Ice reference...', '2015-06-15 01:15:58.000000', NULL, 1),
(7362848, 1153508, 65858, '<td valign="top">The crop feels a little odd, but I like the colors and originality.</td>', 'The crop feels a little odd, but I like the colors and originality.', '2015-06-15 01:16:28.000000', NULL, 1),
(7362852, 1153527, 65858, '<td valign="top">Lol, that''s hilarious!</td>', 'Lol, that''s hilarious!', '2015-06-15 01:17:25.000000', NULL, 1),
(7362853, 1153115, 65858, '<td valign="top">Lovely colors and textures!</td>', 'Lovely colors and textures!', '2015-06-15 01:17:39.000000', NULL, 1),
(7362854, 1152314, 138630, '<td valign="top">So strange.  I love the hair blowing up and the solemn expression.  1P must mean one hour parking?  or something.  Nice comp and excellent tonal range.</td>', 'So strange.  I love the hair blowing up and the solemn expression.  1P must mean one hour parking?  or something.  Nice comp and excellent tonal range.', '2015-06-15 01:18:46.000000', NULL, 1),
(7362859, 1153158, 138630, '<td valign="top">Good title, funny signs.  In a zoo or something?  Surely not street names.  But then again, who knows?  Either way, I find this ordinary except for the title and interesting names.</td>', 'Good title, funny signs.  In a zoo or something?  Surely not street names.  But then again, who knows?  Either way, I find this ordinary except for the title and interesting names.', '2015-06-15 01:20:39.000000', NULL, 1),
(7362862, 1153688, 108069, '<td valign="top">Alki!</td>', 'Alki!', '2015-06-15 01:21:29.000000', NULL, 1),
(7362866, 1153939, 30982, '<td valign="top">Ha!  I''ve seen that sign around here and it DOES stand out as DRIVE like your KIDS.  Which is just plain scary.</td>', 'Ha!  I''ve seen that sign around here and it DOES stand out as DRIVE like your KIDS.  Which is just plain scary.', '2015-06-15 01:24:39.000000', NULL, 1),
(7362867, 1153947, 138630, '<td valign="top">I really like the saturation and colors here - only the essentials, nothing extraneous and that yellow diamond really pops.  I suspect most will find the angle and lens distortion dramatic and a plus . . . I like things straight :(</td>', 'I really like the saturation and colors here - only the essentials, nothing extraneous and that yellow diamond really pops.  I suspect most will find the angle and lens distortion dramatic and a plus . . . I like things straight :(', '2015-06-15 01:24:55.000000', NULL, 1),
(7362869, 1152820, 30982, '<td valign="top">Ya got nothin'' on confusing restrictions compared to LA parking signs... :-)  Nice cheerful and bold shot - angle adds interest!</td>', 'Ya got nothin'' on confusing restrictions compared to LA parking signs... :-)  Nice cheerful and bold shot - angle adds interest!', '2015-06-15 01:25:35.000000', NULL, 1),
(7362872, 1153507, 30982, '<td valign="top">Nice use of a teensy aperture at night to get the pretty star lights.  Good use of other things besides just the signs for interest, too.</td>', 'Nice use of a teensy aperture at night to get the pretty star lights.  Good use of other things besides just the signs for interest, too.', '2015-06-15 01:26:31.000000', NULL, 1),
(7362874, 1152739, 30982, '<td valign="top">This is one of those places you really wish they didn''t have a sign - it seems so harsh and out of place compared to the serene and peaceful scene.</td>', 'This is one of those places you really wish they didn''t have a sign - it seems so harsh and out of place compared to the serene and peaceful scene.', '2015-06-15 01:27:06.000000', NULL, 1),
(7362876, 1153607, 30982, '<td valign="top">Good use of the angle to create a strong dynamic photograph.  Like the rust and age on the old sign, too.</td>', 'Good use of the angle to create a strong dynamic photograph.  Like the rust and age on the old sign, too.', '2015-06-15 01:28:10.000000', NULL, 1),
(7362877, 1153158, 30982, '<td valign="top">Heh - comical combination!</td>', 'Heh - comical combination!', '2015-06-15 01:28:29.000000', NULL, 1),
(7362878, 1153769, 65858, '<td valign="top">I''m struggling to see a road sign (I don''t think the M counts) -- but I''ll give it a 6 for sheer creativity and visual interest.</td>', 'I''m struggling to see a road sign (I don''t think the M counts) -- but I''ll give it a 6 for sheer creativity and visual interest.', '2015-06-15 01:28:34.000000', NULL, 1),
(7362880, 1153371, 138630, '<td valign="top">Beautiful scene - the light and colors are lovely.  The sky is a bit over-processed for me.  I love that the sign and the curve in the road go together and you were able to get both in the composition.  SLOW is a very nice touch.</td>', 'Beautiful scene - the light and colors are lovely.  The sky is a bit over-processed for me.  I love that the sign and the curve in the road go together and you were able to get both in the composition.  SLOW is a very nice touch.', '2015-06-15 01:29:48.000000', NULL, 1),
(7362881, 1153103, 65858, '<td valign="top">Clever composition and nice color scheme, fun!</td>', 'Clever composition and nice color scheme, fun!', '2015-06-15 01:29:49.000000', NULL, 1),
(7362882, 1153688, 30982, '<td valign="top">But it''s such a lovely place to cruise!  Nice light - looks like it was a beautiful evening.  A couple of nits - there''s a bit of haloing going on above the trees, around the power pole, and two kinda big splotches in the sky - on the right side at the edge and upper left about a third in.</td>', 'But it''s such a lovely place to cruise!  Nice light - looks like it was a beautiful evening.  A couple of nits - there''s a bit of haloing going on above the trees, around the power pole, and two kinda big splotches in the sky - on the right side at the edge and upper left about a third in.', '2015-06-15 01:30:09.000000', NULL, 1),
(7362884, 1153062, 138630, '<td valign="top">Winding and slippery.  Thanks for the translation :)  Great scene, colors, lines - those trees are fantastic.  Just a little over-processed for me, but it suits the image well.</td>', 'Winding and slippery.  Thanks for the translation :)  Great scene, colors, lines - those trees are fantastic.  Just a little over-processed for me, but it suits the image well.', '2015-06-15 01:31:00.000000', NULL, 1),
(7362885, 1153500, 30982, '<td valign="top">Great idea for a title!  The shot itself feels just a little soft, but in a way it kinda fits.  Here''s this annoying and graf fiti''d sign against this peaceful, pastoral view....</td>', 'Great idea for a title!  The shot itself feels just a little soft, but in a way it kinda fits.  Here''s this annoying and graf fiti''d sign against this peaceful, pastoral view....', '2015-06-15 01:31:53.000000', NULL, 1),
(7362886, 1152700, 30982, '<td valign="top">Nice catch and very colorful!</td>', 'Nice catch and very colorful!', '2015-06-15 01:32:13.000000', NULL, 1),
(7362888, 1152625, 30982, '<td valign="top">Ha - a bit of overkill.  Nicely seen!</td>', 'Ha - a bit of overkill.  Nicely seen!', '2015-06-15 01:33:06.000000', NULL, 1),
