(7363142, 1153823, 113156, '<td valign="top">The composition is almost too perfect and the grain adds a lot to this well executed perfectly processed scene.</td>', 'The composition is almost too perfect and the grain adds a lot to this well executed perfectly processed scene.', '2015-06-15 07:50:18.000000', NULL, 1),
(7363144, 1153005, 113156, '<td valign="top">Simply powerful.</td>', 'Simply powerful.', '2015-06-15 07:50:47.000000', NULL, 1),
(7363145, 1153959, 113156, '<td valign="top">Struck by the light, powerful photo.</td>', 'Struck by the light, powerful photo.', '2015-06-15 07:51:53.000000', NULL, 1),
(7363167, 1153236, 67258, '<td valign="top">A strong composition, super juxtaposition of the sign and the weather decimated view.  On my screen there don''t look to be any true whites.</td>', 'A strong composition, super juxtaposition of the sign and the weather decimated view.  On my screen there don''t look to be any true whites.', '2015-06-15 08:51:32.000000', NULL, 1),
(7363168, 1152481, 67258, '<td valign="top">An interesting combination of signage, but the lack of detail in the trees (a windy day?) combined with what looks like over-sharpening of the grass lets the photo down for me.  I am interested in knowing what it is that is in half a mile, though!</td>', 'An interesting combination of signage, but the lack of detail in the trees (a windy day?) combined with what looks like over-sharpening of the grass lets the photo down for me.  I am interested in knowing what it is that is in half a mile, though!', '2015-06-15 08:55:28.000000', NULL, 1),
(7363169, 1153790, 67258, '<td valign="top">Not sure that these are necessarily road signs, but that may well be a difference of interpretation on different national lines and so not marking down for that.  Good sharp photo, interesting composition, almost like a found still-life - the boxes add depth to the photo, and more ''story'' to the narrative.</td>', 'Not sure that these are necessarily road signs, but that may well be a difference of interpretation on different national lines and so not marking down for that.  Good sharp photo, interesting composition, almost like a found still-life - the boxes add depth to the photo, and more ''story'' to the narrative.', '2015-06-15 08:59:16.000000', NULL, 1),
(7363170, 1153823, 67258, '<td valign="top">Absolutely love this - the grainy processing adds immensely to the kicked up grit and gravel.</td>', 'Absolutely love this - the grainy processing adds immensely to the kicked up grit and gravel.', '2015-06-15 09:00:55.000000', NULL, 1),
(7363173, 1153818, 67258, '<td valign="top">Very, very pretty - a rural idyll if ever there was one.  compositionally, I do wish that the road sign was a little further to the left of the frame.</td>', 'Very, very pretty - a rural idyll if ever there was one.  compositionally, I do wish that the road sign was a little further to the left of the frame.', '2015-06-15 09:02:37.000000', NULL, 1),
