(7363651, 1153523, 47974, '<td valign="top">Love the play between the two signs, great eye catching it.  I think a square crop would have made this a lot stronger.</td>', 'Love the play between the two signs, great eye catching it.  I think a square crop would have made this a lot stronger.', '2015-06-15 18:32:51.000000', NULL, 1),
(7363654, 1152948, 47974, '<td valign="top">Looks like someone found their sign while working on the cemetery challenge.  Great image.......love the composition, location, play of sign on location, and the great sky.  Not a fan of the processing, maybe a high contrast b&amp;w would have been better.</td>', 'Looks like someone found their sign while working on the cemetery challenge.  Great image.......love the composition, location, play of sign on location, and the great sky.  Not a fan of the processing, maybe a high contrast b&w would have been better.', '2015-06-15 18:36:06.000000', NULL, 1),
