(7364908, 1153577, 76335, '<td valign="top">Clever.</td>', 'Clever.', '2015-06-16 21:57:16.000000', NULL, 1),
(7364909, 1153570, 76335, '<td valign="top">Sad yet kinda funny.</td>', 'Sad yet kinda funny.', '2015-06-16 21:58:07.000000', NULL, 1),
(7364965, 1153150, 116730, '<td valign="top">I love this! I hope you didn''t break any laws stealing that sign, ha!</td>', 'I love this! I hope you didn''t break any laws stealing that sign, ha!', '2015-06-16 23:33:58.000000', NULL, 1),
(7364989, 1152493, 62249, '<td valign="top">I appreciate that you tried something other than a typical head-on shot of a sign. The clouds look over processed, and there''s not much of a story being told by the image.</td>', 'I appreciate that you tried something other than a typical head-on shot of a sign. The clouds look over processed, and there''s not much of a story being told by the image.', '2015-06-16 23:57:54.000000', NULL, 1),
(7364992, 1153950, 62249, '<td valign="top">Too many competing visual elements: the statue, the starred lights, the traffic circle itself, and then the road signs. There''s not a single compelling subject, and the composition doesn''t lead me through the image in a helpful way.</td>', 'Too many competing visual elements: the statue, the starred lights, the traffic circle itself, and then the road signs. There''s not a single compelling subject, and the composition doesn''t lead me through the image in a helpful way.', '2015-06-17 00:00:14.000000', NULL, 1),
(7365001, 1153959, 62249, '<td valign="top">Cool looking clouds. Not much else of interest in the composition, although the placement of the center sign in the glowing hole of the clouds might''ve worked if you''d had an assistant who could''ve illuminated the front of the sign to really tie it into the challenge topic.</td>', 'Cool looking clouds. Not much else of interest in the composition, although the placement of the center sign in the glowing hole of the clouds might''ve worked if you''d had an assistant who could''ve illuminated the front of the sign to really tie it into the challenge topic.', '2015-06-17 00:04:09.000000', NULL, 1),
(7365005, 1153692, 62249, '<td valign="top">Title is good. Might''ve been a stronger image if a single maple leaf were arranged in a pleasing way next to or on the sign.</td>', 'Title is good. Might''ve been a stronger image if a single maple leaf were arranged in a pleasing way next to or on the sign.', '2015-06-17 00:06:46.000000', NULL, 1),
(7365007, 1152763, 62249, '<td valign="top">Good title and interesting processing choices.</td>', 'Good title and interesting processing choices.', '2015-06-17 00:07:42.000000', NULL, 1),
(7365010, 1153982, 62249, '<td valign="top">The best part of the image is the woman with the umbrella seen stepping up between the poles.</td>', 'The best part of the image is the woman with the umbrella seen stepping up between the poles.', '2015-06-17 00:09:34.000000', NULL, 1),
(7365013, 1153290, 62249, '<td valign="top">Heh, the hump does make an amusing spike in the tail light trails.</td>', 'Heh, the hump does make an amusing spike in the tail light trails.', '2015-06-17 00:10:11.000000', NULL, 1),
(7365015, 1153874, 62249, '<td valign="top">Too chaotic, and the out-of-focus rocks in the foreground are too prominent.</td>', 'Too chaotic, and the out-of-focus rocks in the foreground are too prominent.', '2015-06-17 00:11:03.000000', NULL, 1),
(7365017, 1153745, 62249, '<td valign="top">I''m curious to read details about this one after the challenge is over.</td>', 'I''m curious to read details about this one after the challenge is over.', '2015-06-17 00:12:21.000000', NULL, 1),
(7365020, 1152339, 62249, '<td valign="top">Image is too dark. Not enough detail in shadows.</td>', 'Image is too dark. Not enough detail in shadows.', '2015-06-17 00:14:49.000000', NULL, 1),
(7365026, 1153688, 62249, '<td valign="top">A nice composition. Over processed, which has made the sky too splotchy and resulted in odd halos where the trees meet the sky and around the light and telephone poles.</td>', 'A nice composition. Over processed, which has made the sky too splotchy and resulted in odd halos where the trees meet the sky and around the light and telephone poles.', '2015-06-17 00:17:04.000000', NULL, 1),
(7365028, 1153607, 62249, '<td valign="top">Cool looking sign, good clouds and interesting processing. The wood element in the upper left corner detracts from an otherwise interesting shot.</td>', 'Cool looking sign, good clouds and interesting processing. The wood element in the upper left corner detracts from an otherwise interesting shot.', '2015-06-17 00:18:14.000000', NULL, 1),
(7365033, 1153765, 68504, '<td valign="top">ah yes, Sheldon: stinging nettle capital of the world. a warning sign for those who know. nice and green.</td>', 'ah yes, Sheldon: stinging nettle capital of the world. a warning sign for those who know. nice and green.', '2015-06-17 00:20:51.000000', NULL, 1),
(7365037, 1153910, 68504, '<td valign="top">stunning comment on relativity.</td>', 'stunning comment on relativity.', '2015-06-17 00:22:29.000000', NULL, 1),
(7365065, 1153945, 68504, '<td valign="top">I''m a sucker for that yellow outfit.</td>', 'I''m a sucker for that yellow outfit.', '2015-06-17 00:35:52.000000', NULL, 1),
(7365066, 1153823, 68504, '<td valign="top">the noise is eloquent, we snuff it up.</td>', 'the noise is eloquent, we snuff it up.', '2015-06-17 00:37:03.000000', NULL, 1),
(7365067, 1153423, 68504, '<td valign="top">it''s a good cow. she makes a nice sponge too.</td>', 'it''s a good cow. she makes a nice sponge too.', '2015-06-17 00:39:16.000000', NULL, 1),
(7365073, 1153939, 68504, '<td valign="top">a sign begging for annointment.</td>', 'a sign begging for annointment.', '2015-06-17 00:46:43.000000', NULL, 1),
(7365074, 1153936, 68504, '<td valign="top">I have always worried about that "ct" at the end of his name.</td>', 'I have always worried about that "ct" at the end of his name.', '2015-06-17 00:47:24.000000', NULL, 1),
(7365076, 1153852, 68504, '<td valign="top">lose the title. that upper third is truly lovely.</td>', 'lose the title. that upper third is truly lovely.', '2015-06-17 00:48:35.000000', NULL, 1),
(7365078, 1153269, 138630, '<td valign="top">Well coordinated - the sign, the wonderful blur, the title.  Sky''s a little dark for me - not in the ominous sense but in the processing sense.  Maybe my imagination.</td>', 'Well coordinated - the sign, the wonderful blur, the title.  Sky''s a little dark for me - not in the ominous sense but in the processing sense.  Maybe my imagination.', '2015-06-17 00:55:43.000000', NULL, 1),
(7365079, 1153577, 138630, '<td valign="top">Great colors - primary with those touches of secondary - and I love the "slinky" around the arrow.  I find the slash of light in the upper right distracting.</td>', 'Great colors - primary with those touches of secondary - and I love the "slinky" around the arrow.  I find the slash of light in the upper right distracting.', '2015-06-17 00:55:46.000000', NULL, 1),
(7365080, 1153844, 138630, '<td valign="top">This is soooo funy - I really hope people stop long enough to fully appreciate it.  And how long did he hold that pose?  Too bad you couldn''t get just a little shallower dof - that''s a very busy background.</td>', 'This is soooo funy - I really hope people stop long enough to fully appreciate it.  And how long did he hold that pose?  Too bad you couldn''t get just a little shallower dof - that''s a very busy background.', '2015-06-17 00:56:19.000000', NULL, 1),
(7365081, 1153861, 68504, '<td valign="top">strange fruit.</td>', 'strange fruit.', '2015-06-17 00:56:19.000000', NULL, 1),
(7365082, 1153677, 138630, '<td valign="top">Nice one.  Excellent clarity, color, lines.  I like the simplicity of the composition.  And then there''s that camera and the flash and the title.  Yep, good.</td>', 'Nice one.  Excellent clarity, color, lines.  I like the simplicity of the composition.  And then there''s that camera and the flash and the title.  Yep, good.', '2015-06-17 00:56:25.000000', NULL, 1),
(7365083, 1153527, 138630, '<td valign="top">Clever.  Yes, I hate it when I see a sign that I absolutely KNOW is important and supposed to be easily read by any fool . . . and I can''t :(</td>', 'Clever.  Yes, I hate it when I see a sign that I absolutely KNOW is important and supposed to be easily read by any fool . . . and I can''t :(', '2015-06-17 00:56:34.000000', NULL, 1),
(7365085, 1153413, 138630, '<td valign="top">I think I''m looking at a ribbon here.  Well conceived and taken - colors and clarity are yummy.  I don''t mind the blur given the scene.<br/>eta but there are halos around the two guys esp. against the sky that look funny</td>', 'I think I''m looking at a ribbon here.  Well conceived and taken - colors and clarity are yummy.  I don''t mind the blur given the scene.eta but there are halos around the two guys esp. against the sky that look funny', '2015-06-17 00:58:26.000000', NULL, 1),
(7365086, 1153932, 138630, '<td valign="top">Excellent set up and tones.  Love the sign.  Wish the vignette wasn''t so heavy, and the glow/blur.  Still, I''ll bet this will do very well.</td>', 'Excellent set up and tones.  Love the sign.  Wish the vignette wasn''t so heavy, and the glow/blur.  Still, I''ll bet this will do very well.', '2015-06-17 00:58:38.000000', NULL, 1),
(7365088, 1153480, 68504, '<td valign="top">makes you think.</td>', 'makes you think.', '2015-06-17 00:59:27.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7365111, 1153407, 138630, '<td valign="top">Sweet - brother takes care of sister.  I like the plaid shirts and the sepia tone.</td>', 'Sweet - brother takes care of sister.  I like the plaid shirts and the sepia tone.', '2015-06-17 01:11:44.000000', NULL, 1),
(7365211, 1153704, 62249, '<td valign="top">Very punny.</td>', 'Very punny.', '2015-06-17 01:45:42.000000', NULL, 1),
(7365216, 1152625, 62249, '<td valign="top">Subtle, aren''t they? Actually, I like this shot. Works well in B/W.</td>', 'Subtle, aren''t they? Actually, I like this shot. Works well in B/W.', '2015-06-17 01:48:19.000000', NULL, 1),
(7365220, 1153371, 62249, '<td valign="top">The clouds are over processed, but otherwise I like the scene.</td>', 'The clouds are over processed, but otherwise I like the scene.', '2015-06-17 01:49:32.000000', NULL, 1),
(7365222, 1153103, 62249, '<td valign="top">Nicely composed and cropped.</td>', 'Nicely composed and cropped.', '2015-06-17 01:50:15.000000', NULL, 1),
