(7369304, 1153251, 77196, '<td valign="top">This image has been awarded the Auburn pigtail award. <br/><a href="//www.dpchallenge.com/image.php?IMAGE_ID=1153372" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/75000-79999/77196/120/Copyrighted_Image_Reuse_Prohibited_1153372.gif'', strrpos(''//images.dpchallenge.com/images_portfolio/75000-79999/77196/120/Copyrighted_Image_Reuse_Prohibited_1153372.gif'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/75000-79999/77196/120/Copyrighted_Image_Reuse_Prohibited_1153372.gif"/></a> <br/>The unspoken, tacitly ignored truth of life, so poignantly captured in this image of a road, misaligned grave markers, stark black and white, and simple sign "NO EXIT".</td>', 'This image has been awarded the Auburn pigtail award.  The unspoken, tacitly ignored truth of life, so poignantly captured in this image of a road, misaligned grave markers, stark black and white, and simple sign "NO EXIT".', '2015-06-22 09:13:28.000000', NULL, 0),
(7369307, 1153844, 77196, '<td valign="top">This image has been awarded the Blonde pigtail award. <br/><a href="//www.dpchallenge.com/image.php?IMAGE_ID=1153374" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/75000-79999/77196/120/Copyrighted_Image_Reuse_Prohibited_1153374.gif'', strrpos(''//images.dpchallenge.com/images_portfolio/75000-79999/77196/120/Copyrighted_Image_Reuse_Prohibited_1153374.gif'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/75000-79999/77196/120/Copyrighted_Image_Reuse_Prohibited_1153374.gif"/></a> <br/>Always a fan of Monty Python, this image is a great tribute to their humor and style.<br/>Congratulations!<br/></td>', 'This image has been awarded the Blonde pigtail award.  Always a fan of Monty Python, this image is a great tribute to their humor and style.Congratulations!', '2015-06-22 09:17:29.000000', NULL, 0),
